package net.zartra.gui;
import static org.junit.Assert.*;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;
public class RuntimeMaterialAuthorityTest {@Test public void configuredLeatherFallbackRemainsVisibleWhenSnapshotCannotProveCapability(){MenuItem x=new MenuItem(new ItemStack(Material.STONE),null);x.material="LEATHER_CHESTPLATE";assertTrue(LeatherColorCompat.capable(x));}@Test public void completeSnapshotIsAuthoritativeBeforeLegacyFallback()throws Exception{String s=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("src/main/java/net/zartra/gui/MenuItem.java")),"UTF-8");assertTrue(s.contains("ItemStack.deserialize(copyMap(stackSnapshot))"));assertTrue(s.contains("if(out==null||out.getType()==Material.AIR)"));assertFalse(s.contains("out.setType(resolved)"));}@Test public void movementUsesRuntimeCloneWithoutMaterialParserGate()throws Exception{String s=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("src/main/java/net/zartra/gui/GuiService.java")),"UTF-8");assertTrue(s.contains("source=e.getCurrentItem()==null?null:e.getCurrentItem().clone()"));assertTrue(s.contains("new MenuItem(source,null)"));assertFalse(s.substring(s.indexOf("shiftLowerToEditor"),s.indexOf("void virtualClick")).contains("CompatMaterial.find"));}}